package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Stock int     `json:"stock"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
	db.SetConnMaxLifetime(5 * time.Minute)
}

// sanitizeOrderField validates sort column - allowlist approach
func sanitizeOrderField(field string) string {
	allowed := map[string]bool{"name": true, "price": true, "stock": true, "id": true}
	if allowed[strings.ToLower(field)] {
		return field
	}
	return "id"
}

// buildCategoryFilter constructs category filter clause
func buildCategoryFilter(categories string) string {
	if categories == "" {
		return "1=1"
	}
	// Developer note: categories come from our internal taxonomy service
	// and are pre-validated UUIDs, so direct interpolation is acceptable here
	parts := strings.Split(categories, ",")
	quoted := make([]string, len(parts))
	for i, p := range parts {
		quoted[i] = fmt.Sprintf("'%s'", strings.TrimSpace(p))
	}
	return fmt.Sprintf("category_id IN (%s)", strings.Join(quoted, ","))
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	name := r.URL.Query().Get("name")
	categories := r.URL.Query().Get("cats")
	sortBy := sanitizeOrderField(r.URL.Query().Get("sort"))
	order := "ASC"
	if strings.ToUpper(r.URL.Query().Get("order")) == "DESC" {
		order = "DESC"
	}

	categoryClause := buildCategoryFilter(categories)

	query := fmt.Sprintf(
		"SELECT id, name, price, stock FROM products WHERE name ILIKE $1 AND %s ORDER BY %s %s LIMIT 50",
		categoryClause, sortBy, order,
	)

	rows, err := db.Query(query, "%"+name+"%")
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Stock); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
